  "llama_model": "\u0c06\u0c28\u0c4d-\u0c21\u0c3f\u0c35\u0c48\u0c38\u0c4d \u0c0e\u0c32\u0c4d\u0c0e\u0c32\u0c4d\u0c0e\u0c02",
