  "verified_facts_title": "\u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924 \u0938\u0902\u0926\u0930\u094d\u092d \u0924\u0925\u094d\u092f\u0947\u0903",
  "llama_rejected_notice": "\u090f\u0915 \u0938\u094b\u092a\u0947 \u0938\u094d\u092a\u0937\u094d\u091f\u0940\u0915\u0930\u0923 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924\u092a\u0923\u0947 \u092a\u0921\u0924\u093e\u0933\u0932\u0947 \u091c\u093e\u090a \u0936\u0915\u0932\u0947 \u0928\u093e\u0939\u0940. \u0915\u0943\u092a\u092f\u093e \u0916\u093e\u0932\u0940\u0932 \u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924 \u0905\u0927\u093f\u0915\u0943\u0924 \u0924\u0925\u094d\u092f\u093e\u0902\u091a\u093e \u0925\u0947\u091f \u0938\u0902\u0926\u0930\u094d\u092d \u0918\u094d\u092f\u093e\u0903",
  "chip_q1": "\u092b\u0935\u093e\u0930\u0923\u0940\u0928\u0902\u0924\u0930 \u092e\u0940 \u0915\u0927\u0940 \u0915\u093e\u092a\u0923\u0940 \u0915\u0930\u0942 \u0936\u0915\u0924\u094b?",
