  "chip_q3": "\u0938\u0947\u0902\u0926\u094d\u0930\u093f\u092f \u091c\u0948\u0935-\u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u092a\u0930\u094d\u092f\u093e\u092f \u0915\u094b\u0923\u0924\u0947 \u0906\u0939\u0947\u0924?",
  "chip_q4": "\u0930\u094b\u0917\u093e\u091a\u094d\u092f\u093e \u0935\u0947\u0933\u0940 \u092a\u093e\u0923\u0940 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0928\u093e\u091a\u094d\u092f\u093e \u0938\u0942\u091a\u0928\u093e?",
  "weather_title": "\u0939\u0935\u093e\u092e\u093e\u0928 \u0906\u0923\u093f \u092b\u0935\u093e\u0930\u0923\u0940 \u0905\u0928\u0941\u0915\u0942\u0932\u0924\u093e \u092e\u0940\u091f\u0930",
  "weather_desc": "\u0935\u093e\u0930\u093e, \u0924\u093e\u092a\u092e\u093e\u0928 \u0906\u0923\u093f \u092a\u093e\u0935\u0938\u093e\u091a\u0940 \u092a\u0930\u093f\u0938\u094d\u0925\u093f\u0924\u0940 \u0906\u091c \u092b\u0935\u093e\u0930\u0923\u0940\u0938\u093e\u0920\u0940 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0906\u0939\u0947 \u0915\u093e \u0924\u0947 \u0924\u092a\u093e\u0938\u093e \u091c\u0947\u0923\u0947\u0915\u0930\u0942\u0928 \u092a\u094d\u0930\u0935\u093e\u0939 \u0906\u0923\u093f \u0927\u0941\u0933\u0940 \u0939\u094b\u090a \u0928\u092f\u0947.",
  "spray_favorable": "\u0915\u0940\u091f\u0915\u0928\u093e\u0936\u0915 \u092b\u0935\u093e\u0930\u0923\u0940\u0938\u093e\u0920\u0940 \u091a\u093e\u0902\u0917\u0932\u0947 \u0939\u0935\u093e\u092e\u093e\u0928",
  "spray_unfavorable": "\u0906\u0924\u093e \u0915\u0940\u091f\u0915\u0928\u093e\u0936\u0915\u093e\u0902\u091a\u0940 \u092b\u0935\u093e\u0930\u0923\u0940 \u0915\u0930\u0942 \u0928\u0915\u093e",
