  "crop_title": "\u092b\u094b\u091f\u094b\u091a\u093e \u092d\u093e\u0917 \u0928\u093f\u0935\u0921\u093e",
  "crop_hint": "\u091a\u094c\u0915\u091f \u092c\u093e\u0927\u093f\u0924 \u092a\u093e\u0928\u093e\u0935\u0930 \u0915\u093f\u0902\u0935\u093e \u0915\u093f\u0921\u0940\u0935\u0930 \u0938\u0930\u0915\u0935\u093e. \u0906\u0915\u093e\u0930 \u092c\u0926\u0932\u0923\u094d\u092f\u093e\u0938\u093e\u0920\u0940 \u0915\u094b\u092a\u0930\u093e \u0913\u0922\u093e.",
  "crop_use": "\u0939\u093e \u092d\u093e\u0917 \u0924\u092a\u093e\u0938\u093e",
