  "urgent_badge": "\u0ca4\u0cc1\u0cb0\u0ccd\u0ca4\u0cc1-\u0c87\u0c82\u0ca6\u0cc1 \u0c95\u0cbe\u0cb0\u0ccd\u0caf \u0ca8\u0cbf\u0cb0\u0ccd\u0cb5\u0cb9\u0cbf\u0cb8\u0cbf",
