  "sev_share": "\u0cb8\u0cc1\u0cae\u0cbe\u0cb0\u0cc1 {pct} \u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0cb6\u0ca4\u0ca6\u0cb7\u0ccd\u0c9f\u0cc1 \u0c8e\u0cb2\u0cc6\u0c97\u0cb3\u0cc1 \u0cb0\u0ccb\u0c97\u0cb5\u0ca8\u0ccd\u0ca8\u0cc1 \u0ca4\u0ccb\u0cb0\u0cbf\u0cb8\u0cc1\u0ca4\u0ccd\u0ca4\u0cb5\u0cc6",
  "sev_scale": "\u0c95\u0ca1\u0cbf\u0cae\u0cc6\u0c83 10 \u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0cb6\u0ca4\u0c95\u0ccd\u0c95\u0cbf\u0c82\u0ca4 \u0c95\u0ca1\u0cbf\u0cae\u0cc6-\u0cae\u0ca7\u0ccd\u0caf\u0cae\u0c83 10-25%-\u0c85\u0ca7\u0cbf\u0c95\u0c83 25 \u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0cb6\u0ca4\u0c95\u0ccd\u0c95\u0cbf\u0c82\u0ca4 \u0cb9\u0cc6\u0c9a\u0ccd\u0c9a\u0cc1.",
  "sev_note": "\u0cb8\u0cbe\u0ca7\u0ca8\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0c85\u0cb3\u0cc6\u0caf\u0cb2\u0cbe\u0ca6 \u0c88 \u0cab\u0ccb\u0c9f\u0ccb\u0ca6\u0cbf\u0c82\u0ca6 \u0c85\u0c82\u0ca6\u0cbe\u0c9c\u0cc1 \u0cae\u0cbe\u0ca1\u0cbf. \u0c87\u0ca4\u0cb0 \u0c8e\u0cb2\u0cc6\u0c97\u0cb3\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0cb8\u0cb8\u0ccd\u0caf\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0cb8\u0cb9 \u0caa\u0cb0\u0cbf\u0cb6\u0cc0\u0cb2\u0cbf\u0cb8\u0cbf.",
  "sev_not_applicable": "\u0cb5\u0cc8\u0cb0\u0cb8\u0ccd \u0cb0\u0ccb\u0c97\u0c97\u0cb3\u0cbf\u0c97\u0cc6 \u0caf\u0cbe\u0cb5\u0cc1\u0ca6\u0cc7 \u0ca4\u0cc0\u0cb5\u0ccd\u0cb0\u0ca4\u0cc6\u0caf \u0cae\u0c9f\u0ccd\u0c9f\u0cb5\u0cbf\u0cb2\u0ccd\u0cb2\u0c83 \u0cb0\u0ccb\u0c97\u0cb2\u0c95\u0ccd\u0cb7\u0ca3\u0c97\u0cb3\u0cc6\u0c82\u0ca6\u0cb0\u0cc6 \u0cb8\u0c82\u0caa\u0cc2\u0cb0\u0ccd\u0ca3 \u0cb8\u0cb8\u0ccd\u0caf\u0ca6 \u0cb8\u0cc1\u0cb0\u0cc1\u0cb3\u0cbf\u0caf\u0cbe\u0c95\u0cbe\u0cb0\u0ca6 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0cae\u0cca\u0ca8\u0c9a\u0cbe\u0ca6 \u0cac\u0ca3\u0ccd\u0ca3, \u0c95\u0cb2\u0cc6\u0c97\u0cb3\u0cb2\u0ccd\u0cb2. \u0c95\u0cc6\u0cb3\u0c97\u0cbf\u0ca8 \u0cb8\u0cb2\u0cb9\u0cc6\u0caf\u0ca8\u0ccd\u0ca8\u0cc1 \u0c85\u0ca8\u0cc1\u0cb8\u0cb0\u0cbf\u0cb8\u0cbf.",
  "insect_found": "\u0c95\u0cc0\u0c9f \u0caa\u0ca4\u0ccd\u0ca4\u0cc6\u0caf\u0cbe\u0c97\u0cbf\u0ca6\u0cc6",
  "translate_label": "\u0cb8\u0cb2\u0cb9\u0cc6\u0caf\u0cc2 \u0cb8\u0cb9",
  "language_label": "\u0cad\u0cbe\u0cb7\u0cc6 / Language",
  "translate_none": "\u0c87\u0c82\u0c97\u0ccd\u0cb2\u0cbf\u0cb7\u0ccd \u0cae\u0cbe\u0ca4\u0ccd\u0cb0",
  "mt_title": "\u0c88 \u0cb8\u0cbe\u0ca7\u0ca8\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0caf\u0c82\u0ca4\u0ccd\u0cb0 \u0c85\u0ca8\u0cc1\u0cb5\u0cbe\u0ca6-\u0c88 \u0cad\u0cbe\u0cb7\u0cc6\u0caf\u0ca8\u0ccd\u0ca8\u0cc1 \u0cae\u0cbe\u0ca4\u0ca8\u0cbe\u0ca1\u0cc1\u0cb5\u0cb5\u0cb0\u0cc1 \u0c87\u0ca8\u0ccd\u0ca8\u0cc2 \u0caa\u0cb0\u0cbf\u0cb6\u0cc0\u0cb2\u0cbf\u0cb8\u0cbf\u0cb2\u0ccd\u0cb2",
  "mt_withheld": "\u0c95\u0cc6\u0cb2\u0cb5\u0cc1 \u0cb5\u0cbe\u0c95\u0ccd\u0caf\u0c97\u0cb3\u0cc1 \u0c85\u0ca8\u0cc1\u0cb5\u0cbe\u0ca6 \u0caa\u0cb0\u0cc0\u0c95\u0ccd\u0cb7\u0cc6\u0caf\u0cb2\u0ccd\u0cb2\u0cbf \u0cb5\u0cbf\u0cab\u0cb2\u0cb5\u0cbe\u0ca6\u0cb5\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0c85\u0cb5\u0cc1\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0c87\u0c82\u0c97\u0ccd\u0cb2\u0cbf\u0cb7\u0ccd\u0ca8\u0cb2\u0ccd\u0cb2\u0cbf \u0ca4\u0ccb\u0cb0\u0cbf\u0cb8\u0cb2\u0cbe\u0c97\u0cbf\u0ca6\u0cc6.",
  "mt_show_english": "\u0c87\u0c82\u0c97\u0ccd\u0cb2\u0cbf\u0cb7\u0ccd \u0cae\u0cc2\u0cb2\u0cb5\u0ca8\u0ccd\u0ca8\u0cc1 \u0ca4\u0ccb\u0cb0\u0cbf\u0cb8\u0cbf",
  "kb_mt_note": "\u0c90. \u0cb8\u0cbf. \u0c8e. \u0c86\u0cb0\u0ccd., \u0c8e\u0ca8\u0ccd. \u0c90. \u0caa\u0cbf. \u0c8e\u0c9a\u0ccd. \u0c8e\u0c82. \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0c9f\u0cbf. \u0c8e\u0ca8\u0ccd. \u0c8e. \u0caf\u0cc1. \u0caa\u0ccd\u0cb0\u0c95\u0c9f\u0ca3\u0cc6\u0c97\u0cb3 \u0caa\u0ca0\u0ccd\u0caf, \u0caf\u0c82\u0ca4\u0ccd\u0cb0-\u0c85\u0ca8\u0cc1\u0cb5\u0cbe\u0ca6\u0cbf\u0ca4 (\u0c88 \u0cad\u0cbe\u0cb7\u0cc6\u0caf\u0ca8\u0ccd\u0ca8\u0cc1 \u0cae\u0cbe\u0ca4\u0ca8\u0cbe\u0ca1\u0cc1\u0cb5\u0cb5\u0cb0\u0cc1 \u0c87\u0ca8\u0ccd\u0ca8\u0cc2 \u0caa\u0cb0\u0cbf\u0cb6\u0cc0\u0cb2\u0cbf\u0cb8\u0cbf\u0cb2\u0ccd\u0cb2). \u0cb8\u0ccd\u0caa\u0ccd\u0cb0\u0cc7 \u0c89\u0ca4\u0ccd\u0caa\u0ca8\u0ccd\u0ca8\u0c97\u0cb3\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0caa\u0ccd\u0cb0\u0cae\u0cbe\u0ca3\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0caa\u0ccd\u0cb0\u0c95\u0c9f\u0cbf\u0cb8\u0cb2\u0cbe\u0c97\u0cbf\u0ca6\u0cc6.",
  "mt_unavailable": "\u0c95\u0cc3\u0ca4\u0c95 \u0cac\u0cc1\u0ca6\u0ccd\u0ca7\u0cbf\u0cae\u0ca4\u0ccd\u0ca4\u0cc6\u0caf \u0cb5\u0cbf\u0cb5\u0cb0\u0ca3\u0cc6\u0caf\u0cc1 \u0cb8\u0cc1\u0cb0\u0c95\u0ccd\u0cb7\u0ca4\u0cbe \u0caa\u0cb0\u0cc0\u0c95\u0ccd\u0cb7\u0cc6\u0caf\u0cb2\u0ccd\u0cb2\u0cbf \u0c89\u0ca4\u0ccd\u0ca4\u0cc0\u0cb0\u0ccd\u0ca3\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2, \u0c86\u0ca6\u0ccd\u0ca6\u0cb0\u0cbf\u0c82\u0ca6 \u0c88 \u0cab\u0ccb\u0c9f\u0ccb\u0c95\u0ccd\u0c95\u0cc6 \u0caf\u0cbe\u0cb5\u0cc1\u0ca6\u0cc7 \u0c85\u0ca8\u0cc1\u0cb5\u0cbe\u0ca6\u0cb5\u0cbf\u0cb2\u0ccd\u0cb2. \u0c95\u0cc6\u0cb3\u0c97\u0cbf\u0ca8 \u0caa\u0cb0\u0cbf\u0cb6\u0cc0\u0cb2\u0cbf\u0cb8\u0cbf\u0ca6 \u0cb8\u0cb2\u0cb9\u0cc6\u0caf\u0cc1 \u0c87\u0c82\u0c97\u0ccd\u0cb2\u0cbf\u0cb7\u0ccd\u0ca8\u0cb2\u0ccd\u0cb2\u0cbf\u0ca6\u0cc6.",
  "pest_sev_title": "\u0c88 \u0cab\u0ccb\u0c9f\u0ccb\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf\u0cb0\u0cc1\u0cb5 \u0c95\u0cc0\u0c9f\u0c97\u0cb3\u0cc1",
