  "spray_q_wind": "\u0b95\u0bbf\u0bb3\u0bc8\u0b95\u0bb3\u0bcd \u0bb5\u0bb2\u0bc1\u0bb5\u0bbe\u0b95 \u0b85\u0b9a\u0bc8\u0b95\u0bbf\u0bb1\u0ba4\u0bbe, \u0b85\u0bb2\u0bcd\u0bb2\u0ba4\u0bc1 \u0ba4\u0bc2\u0b9a\u0bbf \u0bb5\u0bc0\u0b9a\u0bc1\u0b95\u0bbf\u0bb1\u0ba4\u0bbe?",
