  "spray_notice": "\u09a8\u09c0\u099a\u09c7\u09b0 \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u09ac\u09bf\u0995\u09b2\u09cd\u09aa\u0997\u09c1\u09b2\u09bf \u09a0\u09bf\u0995 \u0986\u0987\u09b8\u09bf\u098f\u0986\u09b0, \u098f\u09a8\u0986\u0987\u09aa\u09bf\u098f\u0987\u099a\u098f\u09ae \u098f\u09ac\u0982 \u099f\u09bf\u098f\u09a8\u098f\u0987\u0989 \u09aa\u09cd\u09b0\u0995\u09be\u09b6\u09a8\u09be \u09a5\u09c7\u0995\u09c7 \u0985\u09a8\u09c1\u09b2\u09bf\u09aa\u09bf \u0995\u09b0\u09be \u09b9\u09af\u09bc\u09c7\u099b\u09c7\u0964 \u09b8\u09b0\u09cd\u09ac\u09a6\u09be \u09b8\u09c1\u09b0\u0995\u09cd\u09b7\u09be\u09ae\u09c2\u09b2\u0995 \u09b8\u09b0\u099e\u09cd\u099c\u09be\u09ae \u09aa\u09b0\u09c1\u09a8 \u098f\u09ac\u0982 \u09ab\u09b8\u09b2\u09c7\u09b0 \u0985\u09aa\u09c7\u0995\u09cd\u09b7\u09be\u09b0 \u09b8\u09ae\u09af\u09bc\u0995\u09be\u09b2 \u09aa\u09b0\u09cd\u09af\u09ac\u09c7\u0995\u09cd\u09b7\u09a3 \u0995\u09b0\u09c1\u09a8\u0964",
  "col_product": "\u09aa\u09a3\u09cd\u09af",
  "col_dose": "\u09a1\u09cb\u099c",
  "col_note": "\u09b2\u09c7\u09ac\u09c7\u09b2/\u0993\u09af\u09bc\u09c7\u099f\u09bf\u0982 \u09a8\u09cb\u099f",
  "col_source": "\u09b8\u09b0\u0995\u09be\u09b0\u09bf \u09b8\u09c2\u09a4\u09cd\u09b0",
  "ask_title": "\u0995\u09bf\u09b7\u09be\u09a3 \u098f\u0986\u0987 \u09b8\u09b9\u0995\u09be\u09b0\u09c0 (\u0985\u09a8-\u09a1\u09bf\u09ad\u09be\u0987\u09b8 \u09b2\u09be\u09ae\u09be)",
  "ask_desc": "\u099f\u09ae\u09c7\u099f\u09cb\u09b0 \u09b0\u09cb\u0997, \u0995\u09c0\u099f\u09aa\u09a4\u0999\u09cd\u0997 \u09a8\u09bf\u09af\u09bc\u09a8\u09cd\u09a4\u09cd\u09b0\u09a3 \u09ac\u09be \u09ab\u09b8\u09b2 \u0995\u09be\u099f\u09be\u09b0 \u09ac\u09bf\u09b0\u09a4\u09bf \u09b8\u09ae\u09cd\u09aa\u09b0\u09cd\u0995\u09c7 \u09af\u09c7 \u0995\u09cb\u09a8\u0993 \u09ab\u09b2\u09cb-\u0986\u09aa \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8 \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09c1\u09a8\u0964",
