  "llama_rejected_notice": "\u098f\u0995\u099f\u09bf \u09b8\u09b0\u09b2\u09c0\u0995\u09c3\u09a4 \u09ac\u09cd\u09af\u09be\u0996\u09cd\u09af\u09be \u09a8\u09bf\u09b0\u09be\u09aa\u09a6\u09c7 \u09af\u09be\u099a\u09be\u0987 \u0995\u09b0\u09be \u09af\u09be\u09af\u09bc\u09a8\u09bf\u0964 \u09a6\u09af\u09bc\u09be \u0995\u09b0\u09c7 \u09a8\u09c0\u099a\u09c7\u09b0 \u09af\u09be\u099a\u09be\u0987\u0995\u09c3\u09a4 \u09b8\u09b0\u0995\u09be\u09b0\u09c0 \u09a4\u09a5\u09cd\u09af\u0997\u09c1\u09b2\u09bf \u09b8\u09b0\u09be\u09b8\u09b0\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0983",
  "chip_q1": "\u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0995\u09b0\u09be\u09b0 \u09aa\u09b0 \u0986\u09ae\u09bf \u0995\u0996\u09a8 \u09ab\u09b8\u09b2 \u09a4\u09c1\u09b2\u09a4\u09c7 \u09aa\u09be\u09b0\u09bf?",
