  "chip_q3": "\u099c\u09c8\u09ac \u099c\u09c8\u09ac \u09a8\u09bf\u09af\u09bc\u09a8\u09cd\u09a4\u09cd\u09b0\u09a3\u09c7\u09b0 \u09ac\u09bf\u0995\u09b2\u09cd\u09aa\u0997\u09c1\u09b2\u09bf \u0995\u09c0 \u0995\u09c0?",
  "chip_q4": "\u09ac\u09cd\u09b2\u09be\u0987\u099f\u09c7\u09b0 \u09b8\u09ae\u09af\u09bc \u099c\u09b2 \u09ac\u09cd\u09af\u09ac\u09b8\u09cd\u09a5\u09be\u09aa\u09a8\u09be\u09b0 \u099f\u09bf\u09aa\u09b8?",
  "weather_title": "\u0986\u09ac\u09b9\u09be\u0993\u09af\u09bc\u09be \u0993 \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0989\u09aa\u09af\u09c1\u0995\u09cd\u09a4\u09a4\u09be \u09ae\u09bf\u099f\u09be\u09b0",
  "weather_desc": "\u09aa\u09cd\u09b0\u09ac\u09be\u09b9 \u098f\u09ac\u0982 \u09a7\u09cb\u09af\u09bc\u09be \u098f\u09a1\u09bc\u09be\u09a4\u09c7 \u09ac\u09be\u09a4\u09be\u09b8, \u09a4\u09be\u09aa\u09ae\u09be\u09a4\u09cd\u09b0\u09be \u098f\u09ac\u0982 \u09ac\u09c3\u09b7\u09cd\u099f\u09bf\u09b0 \u09aa\u09b0\u09bf\u09b8\u09cd\u09a5\u09bf\u09a4\u09bf \u0986\u099c \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0995\u09b0\u09be\u09b0 \u099c\u09a8\u09cd\u09af \u09a8\u09bf\u09b0\u09be\u09aa\u09a6 \u0995\u09bf\u09a8\u09be \u09a4\u09be \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be \u0995\u09b0\u09c1\u09a8\u0964",
  "spray_favorable": "\u0995\u09c0\u099f\u09a8\u09be\u09b6\u0995 \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0995\u09b0\u09be\u09b0 \u099c\u09a8\u09cd\u09af \u09ad\u09be\u09b2\u09cb \u0986\u09ac\u09b9\u09be\u0993\u09af\u09bc\u09be",
  "spray_unfavorable": "\u098f\u0996\u09a8 \u0995\u09c0\u099f\u09a8\u09be\u09b6\u0995 \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0995\u09b0\u09ac\u09c7\u09a8 \u09a8\u09be",
