  "rain_label": "\u09ac\u09c3\u09b7\u09cd\u099f\u09bf\u09b0 \u09b8\u09ae\u09cd\u09ad\u09be\u09ac\u09a8\u09be",
  "spray_tip_title": "\u0995\u09c3\u09b7\u09bf\u09ac\u09bf\u09a6\u09cd\u09af\u09be \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u099f\u09bf\u09aa\u0983",
  "spray_tip_text": "\u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0995\u09b0\u09be\u09b0 \u099c\u09a8\u09cd\u09af \u0986\u09a6\u09b0\u09cd\u09b6 \u09b8\u09ae\u09af\u09bc\u0983 \u09b8\u0995\u09be\u09b2 7\u099f\u09be-10:00 \u09b8\u0995\u09be\u09b2 \u09ac\u09be \u09ac\u09bf\u0995\u09c7\u09b2 4\u099f\u09be-\u09b8\u09a8\u09cd\u09a7\u09cd\u09af\u09be 6\u099f\u09be\u0964 \u09aa\u09cd\u09b0\u09ac\u09b2 \u09ac\u09be\u09a4\u09be\u09b8\u09c7\u09b0 (> 12 \u0995\u09bf\u09ae\u09bf/\u0998\u09a3\u09cd\u099f\u09be) \u09ac\u09bf\u09b0\u09c1\u09a6\u09cd\u09a7\u09c7 \u09b8\u09b0\u09be\u09b8\u09b0\u09bf \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0995\u09b0\u09ac\u09c7\u09a8 \u09a8\u09be\u0964",
  "guide_title": "\u0995\u09c3\u09b7\u0995 \u09a8\u09bf\u09b0\u09be\u09aa\u09a4\u09cd\u09a4\u09be \u0993 \u099c\u09cd\u099e\u09be\u09a8 \u09a8\u09bf\u09b0\u09cd\u09a6\u09c7\u09b6\u09bf\u0995\u09be",
  "helpline_title": "\u09b8\u09b0\u0995\u09be\u09b0\u09bf \u0995\u09c3\u09b7\u0995 \u09b9\u09c7\u09b2\u09cd\u09aa\u09b2\u09be\u0987\u09a8",
  "kisan_call_center": "\u0995\u09bf\u09b7\u09be\u09a3 \u0995\u09b2 \u09b8\u09c7\u09a8\u09cd\u099f\u09be\u09b0\u0983 1800-180-1551 (\u099f\u09cb\u09b2 \u09ab\u09cd\u09b0\u09bf, \u09b8\u0995\u09be\u09b2 6\u099f\u09be \u09a5\u09c7\u0995\u09c7 \u09b0\u09be\u09a4 10\u099f\u09be)",
  "kvk_contact": "\u09ae\u09be\u09a0\u09c7\u09b0 \u09ae\u09be\u099f\u09bf \u0993 \u09aa\u09be\u09a4\u09be \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be\u09b0 \u099c\u09a8\u09cd\u09af \u0986\u09aa\u09a8\u09be\u09b0 \u09b8\u09cd\u09a5\u09be\u09a8\u09c0\u09af\u09bc \u099c\u09c7\u09b2\u09be \u0995\u09c3\u09b7\u09bf \u09ac\u09bf\u099c\u09cd\u099e\u09be\u09a8 \u0995\u09c7\u09a8\u09cd\u09a6\u09cd\u09b0\u09c7\u09b0 (\u0995\u09c7\u09ad\u09bf\u0995\u09c7) \u09b8\u0999\u09cd\u0997\u09c7 \u09af\u09cb\u0997\u09be\u09af\u09cb\u0997 \u0995\u09b0\u09c1\u09a8\u0964",
  "cibrc_title": "\u09b8\u09bf\u0986\u0987\u09ac\u09bf \u098f\u09ac\u0982 \u0986\u09b0\u09b8\u09bf \u0985\u09ab\u09bf\u09b8\u09bf\u09af\u09bc\u09be\u09b2 \u099f\u0995\u09cd\u09b8\u09bf\u09b8\u09bf\u099f\u09bf \u09b2\u09c7\u09ac\u09c7\u09b2 \u0995\u09cb\u09a1",
  "toxic_red": "\u09b2\u09be\u09b2 \u09a4\u09cd\u09b0\u09bf\u09ad\u09c1\u099c\u0983 \u0985\u09a4\u09cd\u09af\u09a8\u09cd\u09a4 \u09ac\u09bf\u09b7\u09be\u0995\u09cd\u09a4 (\u09aa\u09cd\u09b0\u09a5\u09ae \u09b6\u09cd\u09b0\u09c7\u09a3\u09c0)-\u09b8\u09b0\u09cd\u09ac\u09cb\u099a\u09cd\u099a \u09ac\u09bf\u09aa\u09a6, \u09b8\u09b0\u09cd\u09ac\u09be\u09a7\u09bf\u0995 \u09b8\u09c1\u09b0\u0995\u09cd\u09b7\u09be\u09ae\u09c2\u09b2\u0995 \u09b8\u09b0\u099e\u09cd\u099c\u09be\u09ae \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c1\u09a8\u0964",
  "toxic_yellow": "\u09b9\u09b2\u09c1\u09a6 \u09a4\u09cd\u09b0\u09bf\u09ad\u09c1\u099c\u0983 \u0985\u09a4\u09cd\u09af\u09a8\u09cd\u09a4 \u09ac\u09bf\u09b7\u09be\u0995\u09cd\u09a4 (\u09a6\u09cd\u09ac\u09bf\u09a4\u09c0\u09af\u09bc \u09b6\u09cd\u09b0\u09c7\u09a3\u09c0)-\u0995\u09a0\u09cb\u09b0 \u09b8\u09a4\u09b0\u09cd\u0995\u09a4\u09be \u09aa\u09cd\u09b0\u09af\u09bc\u09cb\u099c\u09a8\u0964",
  "toxic_blue": "\u09a8\u09c0\u09b2 \u09a4\u09cd\u09b0\u09bf\u09ad\u09c1\u099c\u0983 \u09ae\u09be\u099d\u09be\u09b0\u09bf \u09ac\u09bf\u09b7\u09be\u0995\u09cd\u09a4 (\u09a4\u09c3\u09a4\u09c0\u09af\u09bc \u09b6\u09cd\u09b0\u09c7\u09a3\u09c0)-\u09b2\u09c7\u09ac\u09c7\u09b2 \u09b8\u09c1\u09b0\u0995\u09cd\u09b7\u09be \u09a8\u09bf\u09af\u09bc\u09ae \u0985\u09a8\u09c1\u09b8\u09b0\u09a3 \u0995\u09b0\u09c1\u09a8\u0964",
  "toxic_green": "\u09b8\u09ac\u09c1\u099c \u09a4\u09cd\u09b0\u09bf\u09ad\u09c1\u099c\u0983 \u09b8\u09be\u09ae\u09be\u09a8\u09cd\u09af \u09ac\u09bf\u09b7\u09be\u0995\u09cd\u09a4 (\u099a\u09a4\u09c1\u09b0\u09cd\u09a5 \u09b6\u09cd\u09b0\u09c7\u09a3\u09c0)-\u09a8\u09bf\u09b0\u09be\u09aa\u09a6 \u099c\u09c8\u09ac-\u09af\u09c1\u0995\u09cd\u09a4\u09bf\u09b8\u0999\u09cd\u0997\u09a4 \u09ac\u09be \u099c\u09c8\u09ac \u09aa\u099b\u09a8\u09cd\u09a6\u0964",
  "golden_rules_title": "\u09a8\u09bf\u09b0\u09be\u09aa\u09a6 \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0995\u09b0\u09be\u09b0 5\u099f\u09bf \u09b8\u09c1\u09ac\u09b0\u09cd\u09a3 \u09a8\u09bf\u09af\u09bc\u09ae",
  "rule_1": "1. \u09b8\u09c1\u09b0\u0995\u09cd\u09b7\u09be \u09b8\u09b0\u099e\u09cd\u099c\u09be\u09ae\u0983 \u09ae\u09be\u09b8\u09cd\u0995, \u0997\u09cd\u09b2\u09be\u09ad\u09b8 \u098f\u09ac\u0982 \u09ac\u09c1\u099f \u09aa\u09b0\u09c1\u09a8\u0964",
  "rule_2": "2. \u0995\u0996\u09a8\u0987 \u0986\u09aa\u09a8\u09be\u09b0 \u09ae\u09c1\u0996 \u09a6\u09bf\u09af\u09bc\u09c7 \u0985\u09ac\u09b0\u09c1\u09a6\u09cd\u09a7 \u0985\u0997\u09cd\u09b0\u09ad\u09be\u0997 \u099c\u09cd\u09ac\u09be\u09b2\u09be\u09ac\u09c7\u09a8 \u09a8\u09be; \u09aa\u09b0\u09bf\u09b7\u09cd\u0995\u09be\u09b0 \u099c\u09b2 \u098f\u09ac\u0982 \u09a8\u09b0\u09ae \u09ac\u09cd\u09b0\u09be\u09b6 \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c1\u09a8\u0964",
  "rule_3": "3. \u0986\u09aa\u09a8\u09be\u09b0 \u09aa\u09bf\u09a0\u09c7 \u09ac\u09be\u09a4\u09be\u09b8 \u09a6\u09bf\u09af\u09bc\u09c7 \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0995\u09b0\u09c1\u09a8, \u0995\u0996\u09a8\u0993 \u09b8\u09cd\u09aa\u09cd\u09b0\u09c7 \u0995\u09c1\u09af\u09bc\u09be\u09b6\u09be\u09b0 \u09ae\u09a7\u09cd\u09af\u09c7 \u09b9\u09be\u0981\u099f\u09ac\u09c7\u09a8 \u09a8\u09be\u0964",
  "rule_4": "4. \u09ab\u09b8\u09b2 \u09a4\u09cb\u09b2\u09be\u09b0 \u0986\u0997\u09c7 \u09ab\u09b8\u09b2\u09c7\u09b0 \u0985\u09aa\u09c7\u0995\u09cd\u09b7\u09be\u09b0 \u09b8\u09ae\u09af\u09bc\u0995\u09be\u09b2 (\u09aa\u09bf. \u098f\u0987\u099a. \u0986\u0987) \u0995\u09a0\u09cb\u09b0\u09ad\u09be\u09ac\u09c7 \u09aa\u09b0\u09cd\u09af\u09ac\u09c7\u0995\u09cd\u09b7\u09a3 \u0995\u09b0\u09c1\u09a8\u0964",
  "rule_5": "5. \u0996\u09be\u09b2\u09bf \u0995\u09c0\u099f\u09a8\u09be\u09b6\u0995\u09c7\u09b0 \u09aa\u09be\u09a4\u09cd\u09b0\u0997\u09c1\u09b2\u09bf \u09a4\u09bf\u09a8\u09ac\u09be\u09b0 \u09a7\u09c1\u09af\u09bc\u09c7 \u09ab\u09c7\u09b2\u09c1\u09a8 \u098f\u09ac\u0982 \u09b8\u09c7\u0997\u09c1\u09b2\u09bf\u0995\u09c7 \u099b\u09bf\u09a6\u09cd\u09b0 \u0995\u09b0\u09c1\u09a8; \u0995\u0996\u09a8\u0987 \u099c\u09b2 \u09ac\u09be \u0996\u09be\u09a6\u09cd\u09af\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09aa\u09c1\u09a8\u09b0\u09be\u09af\u09bc \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09ac\u09c7\u09a8 \u09a8\u09be\u0964",
  "uncertain_title": "\u09b0\u09cb\u0997 \u09a8\u09bf\u09b0\u09cd\u09a3\u09af\u09bc \u0985\u09a8\u09bf\u09b6\u09cd\u099a\u09bf\u09a4",
  "uncertain_desc": "\u098f\u0986\u0987 \u09ae\u09a1\u09c7\u09b2\u099f\u09bf \u098f\u0987 \u09aa\u09be\u09a4\u09be\u099f\u09bf \u09a8\u09bf\u09b0\u09be\u09aa\u09a6\u09c7 \u09a8\u09bf\u09b0\u09cd\u09a3\u09af\u09bc \u0995\u09b0\u09be\u09b0 \u099c\u09a8\u09cd\u09af \u09af\u09a5\u09c7\u09b7\u09cd\u099f \u0986\u09a4\u09cd\u09ae\u09ac\u09bf\u09b6\u09cd\u09ac\u09be\u09b8\u09c0 \u09a8\u09af\u09bc\u0964",
