  "pest_threshold": "\u0b2a\u0b4d\u0b30\u0b15\u0b3e\u0b36\u0b3f\u0b24 \u0b15\u0b3e\u0b30\u0b4d\u0b2f\u0b4d\u0b2f\u0b3c\u0b30 \u0b38\u0b4d\u0b24\u0b30",
  "pest_scouting": "\u0b06\u0b2a\u0b23\u0b19\u0b4d\u0b15 \u0b15\u0b4d\u0b37\u0b47\u0b24\u0b4d\u0b30\u0b15\u0b41 \u0b15\u0b3f\u0b2a\u0b30\u0b3f \u0b2f\u0b3e\u0b1e\u0b4d\u0b1a \u0b15\u0b30\u0b3f\u0b2c\u0b47",
  "level_low": "\u0b15\u0b2e\u0b4d",
  "level_moderate": "\u0b2e\u0b27\u0b4d\u0b5f\u0b2e",
