  "section_mechanical": "\u0b2d\u0b4c\u0b24\u0b3f\u0b15 \u0b0f\u0b2c\u0b02 \u0b2f\u0b3e\u0b28\u0b4d\u0b24\u0b4d\u0b30\u0b3f\u0b15 \u0b28\u0b3f\u0b2f\u0b3c\u0b28\u0b4d\u0b24\u0b4d\u0b30\u0b23",
