  "spray_why_wind": "\u0a24\u0a47\u0a1c\u0a3c \u0a39\u0a35\u0a3e \u0a35\u0a3f\u0a71\u0a1a \u0a1b\u0a3f\u0a21\u0a3c\u0a15\u0a3e\u0a05 \u0a28\u0a3e \u0a15\u0a30\u0a4b\u0964",
