  "about_req_icar": "\u0a06\u0a08. \u0a38\u0a40. \u0a0f. \u0a06\u0a30., \u0a10\u0a71\u0a28. \u0a06\u0a08. \u0a2a\u0a40. \u0a10\u0a71\u0a1a. \u0a10\u0a71\u0a2e. \u0a05\u0a24\u0a47 \u0a1f\u0a40. \u0a10\u0a71\u0a28. \u0a0f. \u0a2f\u0a42. \u0a2a\u0a4d\u0a30\u0a15\u0a3e\u0a38\u0a3c\u0a28\u0a3e\u0a02 \u0a26\u0a40 \u0a38\u0a32\u0a3e\u0a39",
